reg('historicaleconomy4','Exchange and Choice','역사 속 교환과 선택','SS4E1.a–e',(i,lv)=>{
 const common=B('Fictional historical practice model; no actual prices or personal data.','가상의 역사 경제 연습 모형이에요. 실제 가격이나 개인정보가 아니에요.');
 if(i<2){const options=i===0?['repairing a cart|수레 고치기','making a pot|그릇 만들기']:['weaving cloth|천 짜기','growing vegetables|채소 기르기'],first=b(options[0]),second=b(options[1]);return q(B(lv===1?'Only time for one task. The first is chosen. What is the opportunity cost?':'The second is the next-best alternative. What does choosing the first mean?',lv===1?'한 가지 일만 할 시간이 있어요. 첫째를 택할 때 기회비용을 골라요.':'둘째가 다음으로 좋은 선택이에요. 첫째를 택하면 무엇을 포기할까요?'),B(`${common.en} Choices: ${first.en}, ${second.en}.`,`${common.ko} 선택: ${first.ko}, ${second.ko}.`),second,[first,b('Time spent choosing|선택하는 시간')]);}
 if(i<4){const price=5+i,cost=3,quantity=lv===1?1:4;return q(B(i===2?'Price rises while cost stays fixed. Which incentive changes?':'Equal quality, two sellers. Which offer costs less?',i===2?'비용은 같은데 가격이 올라요. 판매자에게 어떤 이익의 기회가 생길까요?':'품질이 같은 두 판매자예요. 어느 쪽 비용이 더 적을까요?'),B(`${common.en} A: ${price} coins each (was ${price-2}); B: ${price+2}; cost ${cost}. Need ${quantity}.`,`${common.ko} 개당 가 ${price}동전(전에는 ${price-2}), 나 ${price+2}동전. 비용 ${cost}동전. ${quantity}개가 필요해요.`),b(i===2?'More potential profit per item|물건당 기대 이익이 늘어요':'Seller A|가 판매자'),[b(i===2?'Less potential profit per item|물건당 기대 이익이 줄어요':'Seller B|나 판매자'),b(i===2?'Prices cannot affect choices|가격은 선택에 영향이 없어요':'Equal cost|같은 비용')]);}
 if(i<6)return q(B(lv===1?'Which economic idea fits?':'Which consequence of the model is supported?',lv===1?'모형에 맞는 경제 개념을 골라요.':'모형에서 뒷받침되는 결과를 골라요.'),B(`${common.en} ${i===4?'One free worker concentrates on weaving.':'One free worker makes pots; another grows food; they choose to trade.'}`,`${common.ko} ${i===4?'자유로운 노동자가 천 짜기에 집중해요.':'한 사람은 그릇을 만들고 다른 사람은 식량을 길러 자발적으로 교환해요.'}`),b(lv===1?(i===4?'Specialization|전문화':'Voluntary trade among specialists|전문가 사이의 자발적 교환'):(i===4?'Focus may improve skill at that task|집중하면 그 일의 기술이 좋아질 수 있어요':'Specialists can obtain goods made by others|전문가는 다른 사람이 만든 물건을 얻을 수 있어요')),(lv===1?(i===4?['Self-sufficiency|자급자족','Resource conservation|자원 절약']:['Trade without specialization|전문화 없는 거래','Production without exchange|교환 없는 생산']):(i===4?['Focus reduces task-specific skill|집중하면 그 일의 기술이 줄어요','Focus provides the raw materials|집중하면 원자재가 생겨요']:['Specialists make goods for their own use instead of trading|전문가는 교환 대신 자신이 쓸 물건을 만들어요','Trading replaces the need for producing goods|교환하면 물건을 생산할 필요가 없어져요'])).map(b));
 if(i<8){const free=i===6;return q(B(lv===1?'Is this exchange voluntary?':'Which distinction is necessary in this record?',lv===1?'자발적으로 택한 교환일까요?':'기록에서 구별해야 할 점을 골라요.'),B(free?'Fictional free traders can accept or refuse an offer.':'Historical slavery forced people to work; they could not freely refuse.',free?'가상의 자유로운 거래자는 제안을 받아들이거나 거절할 수 있어요.':'역사의 노예제는 사람에게 일을 강요했어요. 자유롭게 거절할 수 없었어요.'),b(free?'Voluntary: both can choose|자발적이에요: 둘 다 선택할 수 있어요':'Forced labor is not voluntary trade|강제 노동은 자발적 거래가 아니에요'),[b(free?'Forced because goods changed hands|물건이 오갔으므로 강제예요':'Voluntary because work occurred|일했으니 자발적이에요'),b('Doing work proves consent|일했다는 사실이 동의를 증명해요')]);}
 const foreign=i===9;return q(B(lv===1?'Classify the described trade.':'Which distinction is supported by the locations?',lv===1?'설명한 거래를 분류해요.':'장소에 따라 어떤 구별이 가능할까요?'),B(`${common.en} Goods move from Georgia to ${foreign?'France':'New York'}.`,`${common.ko} 조지아에서 ${foreign?'프랑스':'뉴욕'}으로 물건을 보내요.`),b(foreign?'International trade|국제 무역':'Trade between states within one country|한 나라 안의 주 사이 거래'),[b(foreign?'Trade within one country|한 나라 안의 무역':'Trade between different countries|다른 나라 사이 거래'),b('No goods move|물건을 옮기지 않아요')]);
});
const technology=[
 ['A cotton gin separates seeds from cotton fibers.|조면기는 목화 섬유에서 씨를 분리하는 기계예요.','Cotton gin: seed separation|조면기: 목화 섬유의 씨 분리','Mechanization made this processing faster.|기계로 이 처리 과정이 빨라졌어요.','It sends electrical messages.|전기 신호를 보내요.'],
 ['A steamboat uses steam power to move on water.|증기선은 증기 힘으로 물 위를 가요.','Steamboat: powered water transport|증기선: 증기 동력 수상 운송','Steam power can reduce reliance on wind.|증기 힘으로 바람 의존을 줄일 수 있어요.','Steam propulsion requires a rail track for this boat.|이 배가 증기 동력으로 가려면 철로가 필요해요.'],
 ['A steam locomotive pulls loads along railway tracks.|증기 기관차는 철로에서 짐을 끌어요.','Locomotive: rail transport|기관차: 철로를 따라 짐 운송','Rail transport can move goods over land.|철도는 육지에서 물건을 옮길 수 있어요.','It cleans cotton fibers.|목화 섬유를 다듬어요.'],
 ['A telegraph sends coded messages by electrical signals.|전신은 전기 신호로 부호 메시지를 보내요.','Telegraph: electrical communication|전신: 전기 통신','Communication can travel faster than carrying a letter.|편지를 들고 가는 것보다 소식을 빨리 보낼 수 있어요.','It transports passengers directly.|승객을 직접 옮겨요.'],
 ['Practice data: a cotton process rises from 4 to 12 units per worker-hour.|가상 자료: 목화 처리가 노동자 한 명의 한 시간에 4개에서 12개가 돼요.','Cotton output triples in the model|모형의 목화 처리량이 세 배예요','Output per worker-hour is a productivity measure.|사람 한 명의 시간당 처리량은 생산성 자료예요.','The values are verified historical output.|실제로 확인한 역사 처리량이에요.'],
 ['Practice data: a boat carries 20 rather than 10 equal crates per trip.|가상 자료: 배가 한 번에 같은 상자 10개 대신 20개를 옮겨요.','Boat carrying capacity doubles|배의 모형 운반량이 두 배예요','Equal units allow a meaningful comparison.|단위가 같아 의미 있게 비교할 수 있어요.','Equal transport time establishes equal travel safety.|운송 시간이 같으면 이동 안전도 같아요.'],
 ['Practice data: rail moves an equal load in 2 days rather than 6.|가상 자료: 철도로 같은 짐을 6일 대신 2일에 옮겨요.','Model delivery time decreases|모형의 운송 시간이 줄어요','Time data supports a transport comparison.|시간 자료로 운송을 비교해요.','The load must be three times heavier.|이동 시간 차이가 짐 무게 차이를 보여 줘요.'],
 ['Practice data: a coded message takes minutes rather than several days.|가상 자료: 부호 소식이 며칠 대신 몇 분 걸려요.','Model message time decreases|모형의 통신 시간이 줄어요','Faster information can affect business decisions.|소식이 빨라지면 사업 결정에도 영향을 줄 수 있어요.','Faster delivery establishes the message’s accuracy.|전달이 빠르면 내용의 정확성이 확립돼요.'],
 ['Cotton-processing gains were connected to expanded cotton production and slavery.|목화 처리 기술의 발전은 목화 생산과 노예제의 확대에도 연결됐어요.','Technology gains could accompany harm|기술 발전과 피해가 함께 나타날 수 있어요','More output does not prove fair labor conditions.|처리량이 늘어도 노동 조건이 공정하다는 증거는 아니에요.','Higher output establishes fair working conditions.|생산량이 많으면 공정한 노동 조건이 확립돼요.'],
 ['A table measures output but gives no worker-rights information.|표에는 처리량만 있고 노동자 권리 정보는 없어요.','Output data omits rights evidence|처리량 자료에는 권리 근거가 빠져 있어요','Different questions require different evidence.|질문에 따라 다른 근거가 필요해요.','Output alone proves equal treatment.|처리량만으로 평등한 대우를 증명해요.']
];
reg('productivity4','Technology and Production','기술과 생산','SS4E1.f',(i,lv)=>card(technology,i,lv,'productivity4'));
reg('budget4','Income, Spending and Saving','수입 지출 저축','SS4E2',(i,lv)=>{if(lv===2){const income=30+3*i,spend=12+i,goal=10+i,extra=4+i%3,a=income-spend-extra-goal;return q(B('After regular spending and a new purchase, how much MORE than the savings goal remains?','원래 지출과 새 물건 값을 내고 남은 돈은 저축 목표보다 얼마 더 많을까요?'),B(`Fictional budget: income ${income}, regular spending ${spend}, new purchase ${extra}, savings goal ${goal}.`,`가상 예산: 수입 ${income}, 원래 지출 ${spend}, 새 물건 ${extra}, 저축 목표 ${goal}.`),String(a),[String(a+extra),String(a+goal)]);}const income=20+i*3,spend=12+i,save=income-spend,extra=lv===2?3+i%4:0,m=lv===1?i%3:(i+1)%3;const asks=[B('How much can be saved after this spending?','이만큼 쓰고 얼마를 저축할 수 있을까요?'),B('What income supports the shown spending and saving?','표시한 지출과 저축을 합친 수입을 골라요.'),B('How much spending fits this income and savings goal?','수입과 저축 목표에 맞는 지출을 골라요.')];const a=[save-extra,income,spend+extra][m];return q(asks[m],B(`Fictional budget: ${m===1?'income ?':`income ${income}`}; ${m===2?'spending ?':`spending ${spend+extra}`}; ${m===0?'saving ?':`saving ${save-extra}`}. No borrowing.`,`가상 예산: ${m===1?'수입 ?':`수입 ${income}`}; ${m===2?'지출 ?':`지출 ${spend+extra}`}; ${m===0?'저축 ?':`저축 ${save-extra}`}. 돈을 빌리지 않아요.`),String(a),[String(a+1),String(a+5)]);});

